begin;
with j as (select * from jsonb_to_recordset($law7d0048$[{"code_id":"NK_RF","article_number":"101","version_date":"2000-07-31","article_text":"1. Акт налоговой проверки, другие материалы налоговой проверки, в ходе которых были выявлены нарушения законодательства о налогах и сборах, а также представленные проверяемым лицом (его представителем) письменные возражения по указанному акту должны быть рассмотрены руководителем (заместителем руководителя) налогового органа, проводившего налоговую проверку. По результатам их рассмотрения руководителем (заместителем руководителя) налогового органа в течение 10 дней со дня истечения срока, указанного в пункте 6 статьи 100 настоящего Кодекса, принимается одно из решений, предусмотренных пунктом 7 настоящей статьи, или решение о проведении дополнительных мероприятий налогового контроля. Срок рассмотрения материалов налоговой проверки и вынесения соответствующего решения может быть продлен, но не более чем на один месяц.\n\nВ случае принятия решения о проведении дополнительных мероприятий налогового контроля акт налоговой проверки, другие материалы налоговой проверки и дополнительных мероприятий налогового контроля, а также представленные проверяемым лицом (его представителем) письменные возражения должны быть также рассмотрены руководителем (заместителем руководителя) налогового органа, проводившего налоговую проверку. По результатам их рассмотрения руководителем (заместителем руководителя) налогового органа в течение 10 дней со дня истечения срока, указанного в пункте 62 настоящей статьи, принимается одно из решений, предусмотренных пунктом 7 настоящей статьи. (В редакции Федерального закона от 03.08.2018 № 302-ФЗ)\n\n(Пункт в редакции Федерального закона от 01.05.2016 № 130-ФЗ)\n\nЛицо, в отношении которого проводилась налоговая проверка, вправе участвовать в процессе рассмотрения материалов указанной проверки лично и (или) через своего представителя. При проведении налоговой проверки консолидированной группы налогоплательщиков в процессе рассмотрения материалов налоговой проверки вправе участвовать представители ответственного участника этой группы, других участников такой группы. (В редакции федеральных законов от 27.07.2010 № 229-ФЗ; от 16.11.2011 № 321-ФЗ; от 23.07.2013 № 248-ФЗ; от 01.05.2016 № 130-ФЗ)\n\nЛицо, в отношении которого проводилась налоговая проверка (его представитель), вправе до рассмотрения материалов указанной проверки ознакомиться с материалами налоговой проверки и дополнительных мероприятий налогового контроля в течение срока, предусмотренного для представления письменных возражений пунктом 6 статьи 100 настоящего Кодекса и пунктом 62 настоящей статьи. Налоговый орган обязан обеспечить лицу, в отношении которого проводилась налоговая проверка (его представителю), возможность ознакомиться с материалами налоговой проверки и дополнительных мероприятий налогового контроля на территории налогового органа не позднее двух дней со дня подачи таким лицом соответствующего заявления. Ознакомление с такими материалами осуществляется путем их визуального осмотра, изготовления выписок, снятия копий. По окончании ознакомления составляется протокол в соответствии со статьей 99 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 01.05.2016 № 130-ФЗ) (В редакции Федерального закона от 03.08.2018 № 302-ФЗ)\n\nНеявка лица, в отношении которого проводилась налоговая проверка (его представителя), извещенного надлежащим образом о времени и месте рассмотрения материалов налоговой проверки, не является препятствием для рассмотрения материалов налоговой проверки, за исключением тех случаев, когда участие этого лица будет признано руководителем (заместителем руководителя) налогового органа обязательным для рассмотрения этих материалов.\n\nОбязанность по извещению участников консолидированной группы налогоплательщиков о времени и месте рассмотрения материалов налоговой проверки лежит на ответственном участнике этой группы. Ненадлежащее исполнение указанной обязанности ответственным участником этой группы не является основанием для отложения рассмотрения материалов налоговой проверки. (Дополнение абзацем - Федеральный закон от 16.11.2011 № 321-ФЗ)\n\nНалоговый орган обязан известить участника консолидированной группы налогоплательщиков о времени и месте рассмотрения материалов налоговой проверки, если в акте налоговой проверки по консолидированной группе налогоплательщиков имеется предложение о привлечении этого участника к ответственности за совершение налогового правонарушения. (Дополнение абзацем - Федеральный закон от 16.11.2011 № 321-ФЗ)\n\n1) объявить, кто рассматривает дело и материалы какой налоговой проверки подлежат рассмотрению;\n\n2) установить факт явки лиц, приглашенных для участия в рассмотрении. В случае неявки этих лиц руководитель (заместитель руководителя) налогового органа выясняет, извещены ли участники производства по делу в установленном порядке, и принимает решение о рассмотрении материалов налоговой проверки в отсутствие указанных лиц либо об отложении указанного рассмотрения;\n\n3) в случае участия представителя лица, в отношении которого проводилась налоговая проверка, проверить полномочия этого представителя;\n\n4) разъяснить лицам, участвующим в процедуре рассмотрения, их права и обязанности;\n\n5) вынести решение об отложении рассмотрения материалов налоговой проверки в случае неявки лица, участие которого необходимо для рассмотрения.\n\nПри рассмотрении материалов налоговой проверки исследуются представленные до рассмотрения материалов налоговой проверки доказательства, с которыми лицу, в отношении которого проводилась проверка, была предоставлена возможность ознакомиться, в том числе документы, ранее истребованные у лица, в отношении которого проводилась налоговая проверка (включая участников консолидированной группы налогоплательщиков), документы, представленные в налоговые органы при проведении камеральных или выездных налоговых проверок данных лиц, и иные документы, имеющиеся у налогового органа. Не допускается использование доказательств, полученных с нарушением настоящего Кодекса, а также доказательств, полученных из специальной декларации, представленной в соответствии с Федеральным законом \"О добровольном декларировании физическими лицами активов и счетов (вкладов) в банках и о внесении изменений в отдельные законодательные акты Российской Федерации\", и (или) прилагаемых к ней документов и (или) сведений. Если документы (информация) о деятельности налогоплательщика (консолидированной группы налогоплательщиков) были представлены в налоговый орган с нарушением сроков, установленных настоящим Кодексом, полученные налоговым органом документы (информация) не будут считаться полученными с нарушением настоящего Кодекса. В ходе рассмотрения материалов налоговой проверки может быть принято решение о привлечении в случае необходимости к участию в этом рассмотрении свидетеля, эксперта, специалиста. (В редакции федеральных законов от 16.11.2011 № 321-ФЗ; от 08.06.2015 № 150-ФЗ; от 03.08.2018 № 302-ФЗ)\n\nПри рассмотрении материалов налоговой проверки ведется протокол. (Дополнение абзацем - Федеральный закон от 04.11.2014 № 347-ФЗ)\n\n1) устанавливает, совершало ли лицо, в отношении которого был составлен акт налоговой проверки (участник (участники) консолидированной группы налогоплательщиков), нарушение законодательства о налогах и сборах; (В редакции Федерального закона от 16.11.2011 № 321-ФЗ)\n\n2) устанавливает, образуют ли выявленные нарушения состав налогового правонарушения;\n\n3) устанавливает, имеются ли основания для привлечения лица к ответственности за совершение налогового правонарушения;\n\n4) выявляет обстоятельства, исключающие вину лица в совершении налогового правонарушения, либо обстоятельства, смягчающие или отягчающие ответственность за совершение налогового правонарушения.\n\nВ решении о проведении дополнительных мероприятий налогового контроля излагаются обстоятельства, вызвавшие необходимость проведения таких дополнительных мероприятий, указываются срок и конкретная форма их проведения. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nВ качестве дополнительных мероприятий налогового контроля может проводиться истребование документов в соответствии со статьями 93 и 931 настоящего Кодекса, допрос свидетеля, проведение экспертизы.\n\nДополнение к акту налоговой проверки должно быть составлено и подписано должностными лицами налогового органа, проводящими дополнительные мероприятия налогового контроля, в течение пятнадцати дней со дня окончания таких мероприятий.\n\nДополнение к акту налоговой проверки с приложением материалов, полученных в результате проведения дополнительных мероприятий налогового контроля, в течение пяти дней с даты этого дополнения должно быть вручено лицу, в отношении которого проводилась налоговая проверка (его представителю), под расписку или передано иным способом, свидетельствующим о дате его получения указанным лицом (его представителем), если иное не предусмотрено настоящим пунктом.\n\nПри проведении дополнительных мероприятий налогового контроля в отношении консолидированной группы налогоплательщиков дополнение к акту налоговой проверки в течение десяти дней с даты этого дополнения вручается ответственному участнику консолидированной группы налогоплательщиков в порядке, установленном настоящим пунктом.\n\nДополнение к акту налоговой проверки направляется иностранной организации (за исключением международной организации, дипломатического представительства, иностранного лица, подлежащего постановке на учет в налоговом органе в соответствии с пунктом 46 статьи 83 настоящего Кодекса), не осуществляющей деятельность на территории Российской Федерации через обособленное подразделение, по почте заказным письмом по адресу, содержащемуся в Едином государственном реестре налогоплательщиков. Датой вручения этого дополнения к акту налоговой проверки считается двадцатый день, считая с даты отправки заказного письма. (В редакции  Федерального закона от 29.05.2024 № 100-ФЗ)\n\nПри этом документы, полученные от лица, в отношении которого проводилась налоговая проверка, к дополнению к акту налоговой проверки не прилагаются.\n\nВ случае, если лицо, в отношении которого проводилась налоговая проверка (его представитель), уклоняется от получения дополнения к акту налоговой проверки, такой факт отражается в дополнении к акту налоговой проверки. В этом случае дополнение к акту налоговой проверки направляется по почте заказным письмом по месту нахождения организации (обособленного подразделения) или месту жительства физического лица и считается полученным на шестой день с даты отправки заказного письма.\n\n(Дополнение пунктом - Федеральный закон от 01.05.2016 № 130-ФЗ) (В редакции Федерального закона от 03.08.2018 № 302-ФЗ)\n\n1) о привлечении к ответственности за совершение налогового правонарушения. При проверке консолидированной группы налогоплательщиков в указанном решении может содержаться указание о привлечении к ответственности одного или нескольких участников этой группы; (В редакции Федерального закона от 16.11.2011 № 321-ФЗ)\n\n2) об отказе в привлечении к ответственности за совершение налогового правонарушения.\n\nВ решении об отказе в привлечении к ответственности за совершение налогового правонарушения излагаются обстоятельст\n\nва, послужившие основанием для такого отказа. В решении об отказе в привлечении к ответственности за налоговые правонарушения может быть указан размер недоимки, если эта недоимка была выявлена в ходе проверки. (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nВ решении о привлечении к ответственности за совершение налогового правонарушения либо в решении об отказе в привлечении к ответственности за совершение налогового правонарушения указываются срок, в течение которого лицо, в отношении которого вынесено решение, вправе обжаловать указанное решение, порядок обжалования решения в вышестоящий налоговый орган, а также наименование органа, его место нахождения, другие необходимые сведения. (В редакции Федерального закона от 02.07.2013 № 153-ФЗ)\n\nВ случае обнаружения в ходе налоговой проверки суммы налога, излишне возмещенной на основании решения налогового органа, в решении о привлечении к ответственности за совершение налогового правонарушения либо в решении об отказе в привлечении к ответственности за совершение налогового правонарушения указанная сумма признается недоимкой. (Дополнение абзацем - Федеральный закон от 23.07.2013 № 248-ФЗ) (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\nВ случае, если размер недоимки, выявленный в результате налоговой проверки, позволяет предполагать факт совершения нарушения законодательства о налогах и сборах, содержащего признаки преступления, в решении о привлечении к ответственности за совершение налогового правонарушения либо в решении об отказе в привлечении к ответственности за совершение налогового правонарушения должно содержаться предупреждение лица, в отношении которого вынесено соответствующее решение, об обязанности налогового органа в случае неуплаты этим лицом суммы недоимки в полном объеме направить в установленный в соответствии с пунктом 3 статьи 32 настоящего Кодекса срок материалы в следственные органы для решения вопроса о возбуждении уголовного дела. (Дополнение абзацем - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\nВ случае подачи апелляционной жалобы на решение налогового органа указанное решение вступает в силу в порядке, предусмотренном статьей 1012 настоящего Кодекса. (В редакции Федерального закона от 02.07.2013 № 153-ФЗ)\n\nЛицо, в отношении которого вынесено соответствующее решение, вправе исполнить решение полностью или в части до вступления его в силу. При этом подача апелляционной жалобы не лишает это лицо права исполнить не вступившее в силу решение полностью или в части.\n\nРуководитель (заместитель руководителя) налогового органа вправе принять решение об отмене обеспечительных мер или решение о замене обеспечительных мер в случаях, предусмотренных настоящим пунктом и пунктом 11 настоящей статьи. Решение об отмене (замене) обеспечительных мер вступает в силу со дня его вынесения. (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nОбеспечительными мерами могут быть:\n\n1) запрет на отчуждение (передачу в залог) имущества налогоплательщика без согласия налогового органа. Предусмотренный настоящим подпунктом запрет на отчуждение (передачу в залог) производится последовательно в отношении:\n\nнедвижимого имущества, в том числе не участвующего в производстве продукции (работ, услуг);\n\nтранспортных средств, ценных бумаг, предметов дизайна служебных помещений;\n\nиного имущества, за исключением готовой продукции, сырья и материалов;\n\nготовой продукции, сырья и материалов.\n\nПри этом запрет на отчуждение (передачу в залог) имущества каждой последующей группы применяется в случае, если совокупная стоимость имущества из предыдущих групп, определяемая по данным бухгалтерского учета, меньше общей суммы недоимки, пеней и штрафов, подлежащей уплате на основании решения о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения;\n\n2) приостановление операций по счетам в банке, по счетам цифрового рубля в порядке, установленном статьей 76 настоящего Кодекса. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nПриостановление операций по счетам в банке, по счетам цифрового рубля в порядке принятия обеспечительных мер может применяться только после наложения запрета на отчуждение (передачу в залог) имущества и в случае, если совокупная стоимость такого имущества по данным бухгалтерского учета меньше общей суммы недоимки, пеней и штрафов, подлежащей уплате на основании решения о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nПриостановление операций по счетам в банке, по счетам цифрового рубля допускается в отношении разницы между общей суммой недоимки, пеней и штрафов, указанной в решении о привлечении к ответственности за совершение налогового правонарушения или решении об отказе в привлечении к ответственности за совершение налогового правонарушения, и стоимостью имущества, не подлежащего отчуждению (передаче в залог) в соответствии с подпунктом 1 настоящего пункта. (В редакции  Федерального закона от 19.12.2023 № 610-ФЗ)\n\nАбзац. (Дополнение абзацем - Федеральный закон от 16.11.2011 № 321-ФЗ) (Утратил силу - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\n1) банковскую гарантию, отвечающую требованиям, установленным статьей 741 настоящего Кодекса, и подтверждающую, что гарант обязывается перед налоговыми органами уплатить в соответствии с условиями даваемого гарантом обязательства указанную в решении о привлечении к ответственности за совершение налогового правонарушения или в решении об отказе в привлечении к ответственности за совершение налогового правонарушения сумму задолженности в случае неуплаты этой суммы принципалом в установленный срок, по представленному налоговым органом гаранту в письменной форме или электронной форме по телекоммуникационным каналам связи требованию об уплате этой суммы; (В редакции  федеральных законов от 14.07.2022 № 263-ФЗ, от 31.07.2023 № 389-ФЗ)\n\n2) залог ценных бумаг, обращающихся на организованном рынке ценных бумаг, или залог иного имущества, оформленный в порядке, предусмотренном статьей 73 настоящего Кодекса;\n\n3) поручительство третьего лица, оформленное в порядке, предусмотренном статьей 74 настоящего Кодекса.\n\nРешение о принятии обеспечительных мер отменяется также по заявлению налогоплательщика, в отношении имущества которого приняты указанные обеспечительные меры, в части, соответствующей объему исполненного решения о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения, либо в части, отмененной вышестоящим налоговым органом или судом.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nВ случае направления копии решения по почте заказным письмом решение считается полученным по истечении шести дней с даты направления заказного письма. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 229-ФЗ)\n\n14. Несоблюдение должностными лицами налоговых органов требований, установленных настоящим Кодексом, может являться основанием для отмены решения налогового органа вышестоящим налоговым органом или судом.\n\nНарушение существенных условий процедуры рассмотрения материалов налоговой проверки является основанием для отмены вышестоящим налоговым органом или судом решения налогового органа о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения. К таким существенным условиям относится обеспечение возможности лица, в отношении которого проводилась проверка, участвовать в процессе рассмотрения материалов налоговой проверки лично и (или) через своего представителя и обеспечение возможности налогоплательщика представить объяснения.\n\nОснованиями для отмены указанного решения налогового органа вышестоящим налоговым органом или судом могут являться иные нарушения процедуры рассмотрения материалов налоговой проверки, если только такие нарушения привели или могли привести к принятию руководителем (заместителем руководителя) налогового органа неправомерного решения.\n\n15. По выявленным налоговым органом нарушениям, за которые физические лица или должностные лица организаций подлежат привлечению к административной ответственности, уполномоченное должностное лицо налогового органа, проводившее проверку, составляет протокол об административном правонарушении в пределах своей компетенции. Рассмотрение дел об этих правонарушениях и применение административных наказаний в отношении физических лиц и должностных лиц организаций, виновных в их совершении, производятся в соответствии с законодательством об административных правонарушениях.\n\nПри этом течение сроков взыскания, предусмотренных настоящим Кодексом, приостанавливается на период приостановления исполнения решения о взыскании соответствующей задолженности. (В редакции  федеральных законов от 29.09.2019 № 325-ФЗ, от 14.07.2022 № 263-ФЗ)\n\nВ случае, если по итогам рассмотрения материалов будет вынесено постановление об отказе в возбуждении уголовного дела или постановление о прекращении уголовного дела, а также если по соответствующему уголовному делу будет вынесен оправдательный приговор, руководитель (заместитель руководителя) налогового органа не позднее дня, следующего за днем получения уведомления об этих фактах от следственных органов, выносит решение о возобновлении исполнения принятых в отношении этого физического лица решения о привлечении к ответственности за совершение налогового правонарушения и решения о взыскании соответствующей задолженности.  (В редакции  федеральных законов от 28.12.2010 № 404-ФЗ, от 29.09.2019 № 325-ФЗ, от 14.07.2022 № 263-ФЗ)\n\nВ случае, если действие (бездействие) налогоплательщика (плательщика сбора, плательщика страховых взносов, налогового агента) - физического лица, послужившее основанием для привлечения его к ответственности за совершение налогового правонарушения, стало основанием для вынесения обвинительного приговора в отношении данного физического лица, налоговый орган отменяет вынесенное решение в части привлечения налогоплательщика (плательщика сбора, плательщика страховых взносов, налогового агента) - физического лица к ответственности за совершение налогового правонарушения. (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nСледственные органы, получившие от налоговых органов материалы в соответствии с пунктом 3 статьи 32 настоящего Кодекса, обязаны направлять в налоговые органы уведомления о результатах рассмотрения этих материалов не позднее дня, следующего за днем принятия соответствующего решения. (В редакции Федерального закона от 28.12.2010 № 404-ФЗ)\n\nКопии решений налогового органа, указанных в настоящем пункте, в течение пяти дней со дня вынесения соответствующего решения передаются (направляются) налоговым органом лицу, в отношении которого вынесено соответствующее решение (его представителю). (В редакции Федерального закона от 23.07.2013 № 248-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.12.2009 № 383-ФЗ)\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 101. Вынесение решения по результатам рассмотрения материалов налоговой проверки","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"37eb80273c8c89ca6c8b85e2063b2aeeedf21c0eae901f15aa34a302ed99fc13"},{"code_id":"NK_RF","article_number":"101.1","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 09.07.1999 № 154-ФЗ) (Утратила силу - Федеральный закон от 27.07.2006 № 137-ФЗ)","article_title":"Статья 101.1. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"da905c5b8d842d66095408c41819a3a33c99abf499c463a1c920b89c47c7e307"},{"code_id":"NK_RF","article_number":"101.2","version_date":"2000-07-31","article_text":"1. В случае обжалования решения налогового органа о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения в апелляционном порядке такое решение вступает в силу в части, не отмененной вышестоящим налоговым органом, и в необжалованной части со дня принятия вышестоящим налоговым органом решения по апелляционной жалобе.\n\n2. В случае, если вышестоящий налоговый орган, рассматривающий апелляционную жалобу, отменит решение нижестоящего налогового органа и примет новое решение, такое решение вышестоящего налогового органа вступает в силу со дня его принятия.\n\n3. В случае, если вышестоящий налоговый орган оставит без рассмотрения апелляционную жалобу, решение нижестоящего налогового органа вступает в силу со дня принятия вышестоящим налоговым органом решения об оставлении апелляционной жалобы без рассмотрения, но не ранее истечения срока подачи апелляционной жалобы.\n\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 137-ФЗ) (В редакции Федерального закона от 02.07.2013 № 153-ФЗ)","article_title":"Статья 101.2. Вступление в силу решения налогового органа о привлечении к ответственности за совершение налогового правонарушения и решения об отказе в привлечении к ответственности за совершение налогового правонарушения при обжаловании в апелляционном порядке","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"72b5f1b7867958b95320ce2b5a7793b627ef1289292dca5c9e220fcf905da6db"},{"code_id":"NK_RF","article_number":"101.3","version_date":"2000-07-31","article_text":"1. Решение о привлечении к ответственности за совершение налогового правонарушения или решение об отказе в привлечении к ответственности за совершение налогового правонарушения подлежит исполнению со дня его вступления в силу.\n\n2. Обращение соответствующего решения к исполнению возлагается на налоговый орган, вынесший это решение. В случае рассмотрения жалобы вышестоящим налоговым органом в апелляционном порядке вступившее в силу соответствующее решение направляется в налоговый орган, вынесший первоначальное решение, в течение трех дней со дня вступления в силу соответствующего решения.\n\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 137-ФЗ)","article_title":"Статья 101.3. Исполнение решения налогового органа о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5e3803a1a53cdc0ac1ebf152e0f4388f64a84eb0c23e3ff8ca97aa37d681d7fa"},{"code_id":"NK_RF","article_number":"101.4","version_date":"2000-07-31","article_text":"1. При обнаружении фактов, свидетельствующих о нарушениях законодательства о налогах и сборах, ответственность за которые установлена настоящим Кодексом (за исключением налоговых правонарушений, дела о выявлении которых рассматриваются в порядке, установленном статьей 101\n\nнастоящего Кодекса), должностным лицом налогового органа в течение 10 дней со дня выявления указанного нарушения должен быть составлен в установленной форме акт, подписываемый этим должностным лицом и лицом, совершившим такое нарушение. Об отказе лица, совершившего нарушение законодательства о налогах и сборах, подписать акт делается соответствующая запись в этом акте. (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nПри рассмотрении акта могут оглашаться составленный акт, иные материалы мероприятий налогового контроля, а также письменные возражения лица, привлекаемого к ответственности за совершение налогового правонарушения. Отсутствие письменных возражений не лишает этого лица права давать свои объяснения на стадии рассмотрения акта.\n\nПри рассмотрении акта заслушиваются объяснения лица, привлекаемого к ответственности, исследуются иные доказательства. Не допускается использование доказательств, полученных с нарушением настоящего Кодекса, а также доказательств, полученных из специальной декларации, представленной в соответствии с Федеральным законом \"О добровольном декларировании физическими лицами активов и счетов (вкладов) в банках и о внесении изменений в отдельные законодательные акты Российской Федерации\", и (или) прилагаемых к ней документов и (или) сведений. Если документы (информация) были представлены лицом, привлекаемым к ответственности, в налоговый орган с нарушением установленных настоящим Кодексом сроков, то полученные документы (информация) не будут считаться полученными с нарушением настоящего Кодекса. (В редакции федеральных законов от 26.11.2008 № 224-ФЗ; от 08.06.2015 № 150-ФЗ)\n\nПри рассмотрении материалов налоговой проверки ведется протокол. (Дополнение абзацем - Федеральный закон от 04.11.2014 № 347-ФЗ)\n\nВ ходе рассмотрения акта и других материалов мероприятий налогового контроля может быть принято решение о привлечении в случае необходимости к участию в этом рассмотрении свидетеля, эксперта, специалиста.\n\nВ ходе рассмотрения акта и других материалов руководитель (заместитель руководителя) налогового органа:\n\n1) устанавливает, допускало ли лицо, в отношении которого был составлен акт, нарушения законодательства о налогах и сборах;\n\n2) устанавливает, образуют ли выявленные нарушения состав налоговых правонарушений, содержащихся в настоящем Кодексе;\n\n3) устанавливает, имеются ли основания для привлечения лица, в отношении которого был составлен акт, к ответственности за совершение налогового правонарушения;\n\n4) выявляет обстоятельства, исключающие вину лица в совершении налогового правонарушения, или обстоятельства, смягчающие или отягчающие ответственность за совершение налогового правонарушения.\n\n1) о привлечении лица к ответственности за налоговое правонарушение;\n\n2) об отказе в привлечении лица к ответственности за налоговое правонарушение.\n\nВ решении о привлечении к ответственности за совершение налогового правонарушения указываются срок, в течение которого лицо, в отношении которого вынесено указанное решение, вправе обжаловать это решение, порядок обжалования решения в вышестоящий налоговый орган, а также указываются наименование органа, место его нахождения, другие необходимые сведения. (В редакции Федерального закона от 02.07.2013 № 153-ФЗ)\n\n12. Несоблюдение должностными лицами налоговых органов требований, установленных настоящим Кодексом, может являться основанием для отмены решения налогового органа вышестоящим налоговым органом или судом.\n\nНарушение существенных условий процедуры рассмотрения акта и иных материалов мероприятий налогового контроля является основанием для отмены решения налогового органа вышестоящим налоговым органом или судом. К таким существенным условиям относится обеспечение возможности лица, в отношении которого был составлен акт, участвовать в процессе рассмотрения материалов лично и (или) через своего представителя и обеспечение возможности этого лица представить объяснения.\n\nОснованиями для отмены решения налогового органа вышестоящим налоговым органом или судом могут являться иные нарушения процедуры рассмотрения материалов, если только такие нарушения привели или могли привести к принятию неправильного решения.\n\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 137-ФЗ)","article_title":"Статья 101.4. Производство по делу о предусмотренных настоящим Кодексом налоговых правонарушениях","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5b4dc0bf258c06e61ba82295a000967a82c9d62dc5a588cbaa65aeb7e81902a7"},{"code_id":"NK_RF","article_number":"102","version_date":"2000-07-31","article_text":"1) являющихся общедоступными, в том числе ставших таковыми с согласия их обладателя - налогоплательщика (плательщика страховых взносов). Такое согласие представляется по выбору налогоплательщика (плательщика страховых взносов) в отношении всех сведений или их части, полученных налоговым органом, по форме, формату и в порядке, утверждаемым федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов; (В редакции федеральных законов от 01.05.2016 № 134-ФЗ; от 03.07.2016 № 243-ФЗ)\n\n2) об идентификационном номере налогоплательщика;\n\n(Подпункт 3 исключен  - Федеральный закон от 09.07.1999 № 154-ФЗ)\n\n3) о нарушениях законодательства о налогах и сборах (в том числе сумме задолженности при ее наличии) и мерах ответственности за эти нарушения;  (В редакции  федеральных законов от 09.07.1999 № 154-ФЗ, от 01.05.2016 № 134-ФЗ, от 14.07.2022 № 263-ФЗ)\n\n4) предоставляемых налоговым (таможенным) или правоохранительным органам других государств в соответствии с международными договорами (соглашениями), одной из сторон которых является Российская Федерация, о взаимном сотрудничестве между налоговыми (таможенными) или правоохранительными органами (в части сведений, предоставленных этим органам), в том числе в рамках международного автоматического обмена информацией; (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 27.11.2017 № 340-ФЗ)\n\n5) предоставляемых избирательным комиссиям в соответствии с законодательством о выборах по результатам проверок налоговым органом сведений о размере и об источниках доходов кандидата и его супруга, а также об имуществе, принадлежащем кандидату и его супругу на праве собственности; (Дополнение подпунктом - Федеральный закон от 26.04.2007 № 64-ФЗ)\n\n6) предоставляемых в Государственную информационную систему о государственных и муниципальных платежах, предусмотренную Федеральным законом от 27 июля 2010 года № 210-ФЗ \"Об организации предоставления государственных и муниципальных услуг\"; (Дополнение подпунктом - Федеральный закон от 27.06.2011 № 162-ФЗ)\n\n7) о специальных налоговых режимах, применяемых налогоплательщиками, а также об участии налогоплательщика в консолидированной группе налогоплательщиков; (Дополнение подпунктом - Федеральный закон от 30.09.2013 № 267-ФЗ)\n\n8) предоставляемых органам местного самоуправления (органам государственной власти городов федерального значения Москвы, Санкт-Петербурга и Севастополя, органам публичной власти федеральной территории \"Сириус\") в целях осуществления контроля за полнотой и достоверностью информации, представленной плательщиками местных сборов, для расчета сборов, а также о суммах задолженности плательщиков местных сборов; (Дополнение подпунктом - Федеральный закон от 29.11.2014 № 382-ФЗ)  (В редакции  федеральных законов от 01.05.2016 № 134-ФЗ, от 11.06.2021 № 199-ФЗ, от 14.07.2022 № 263-ФЗ)\n\n9) о среднесписочной численности работников организации за календарный год, предшествующий году размещения указанных сведений в информационно-телекоммуникационной сети \"Интернет\" в соответствии с пунктом 11 настоящей статьи; (Дополнение подпунктом - Федеральный закон от 01.05.2016 № 134-ФЗ)\n\n10) перечисленных организацией в календарном году, предшествующем году размещения указанных сведений в информационно-телекоммуникационной сети \"Интернет\" в соответствии с пунктом 11 настоящей статьи, в качестве единого налогового платежа суммах денежных средств с указанием их принадлежности, определенной в соответствии с пунктами 7 - 9 статьи 45 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 01.05.2016 № 134-ФЗ) (В редакции  федеральных законов от 03.07.2016 № 243-ФЗ, от 14.07.2022 № 263-ФЗ)\n\n11) о суммах доходов и расходов по данным бухгалтерской (финансовой) отчетности организации за год, предшествующий году размещения указанных сведений в информационно-телекоммуникационной сети \"Интернет\" в соответствии с пунктом 11 настоящей статьи; (Дополнение подпунктом - Федеральный закон от 01.05.2016 № 134-ФЗ)\n\n12) о постановке на учет в налоговых органах иностранных лиц (за исключением сведений о постановке на учет в налоговом органе по месту нахождения недвижимого имущества и (или) транспортных средств); (Дополнение подпунктом - Федеральный закон от 03.07.2016 № 244-ФЗ) (В редакции  федеральных законов от 31.07.2023 № 389-ФЗ, от 29.05.2024 № 100-ФЗ)\n\n13) о постановке на учет в налоговых органах физических лиц в соответствии с пунктом 73 статьи 83 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 30.11.2016 № 401-ФЗ)\n\n14) о принятых налоговым органом обеспечительных мерах и применении способов обеспечения исполнения обязанности по уплате налогов, сборов, страховых взносов, предусмотренных настоящим Кодексом; (Дополнение подпунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n15) предоставляемых по запросам Федерального казначейства, финансовых органов субъектов Российской Федерации, муниципальных образований и федеральной территории \"Сириус\" сведений о принадлежности денежных средств, перечисленных в качестве единого налогового платежа, определенной в соответствии с пунктами 7 - 9 статьи 45 настоящего Кодекса, к налогам, сборам, страховым взносам, являющимся источниками формирования доходов соответствующего бюджета; (Дополнение подпунктом - Федеральный закон от 14.07.2022 № 263-ФЗ)\n\n16) о номере записи федерального регистра сведений о населении. (Дополнение подпунктом - Федеральный закон от 08.08.2024 № 259-ФЗ)\n\nСроки и период размещения сведений, указанных в абзаце первом настоящего пункта, порядок их формирования и размещения утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение пунктом - Федеральный закон от 01.05.2016 № 134-ФЗ)\n\nК разглашению налоговой тайны относится, в частности, использование или передача другому лицу информации, составляющей коммерческую тайну (секрет производства) налогоплательщика, плательщика страховых взносов и ставшей известной должностному лицу налогового органа, органа внутренних дел, следственного органа, органа государственного внебюджетного фонда или таможенного органа, привлеченному специалисту или эксперту при исполнении ими своих обязанностей. (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 02.01.2000 № 13-ФЗ; от 30.06.2003 № 86-ФЗ; от 28.12.2010 № 404-ФЗ; от 11.07.2011 № 200-ФЗ; от 03.07.2016 № 243-ФЗ)\n\nПо выбору налогоплательщика (плательщика страховых взносов) согласие, предусмотренное абзацем первым настоящего пункта, может быть представлено в отношении всех сведений, полученных налоговым органом, или их части. Указанное согласие направляется в налоговый орган в электронной форме. Формат и порядок направления указанного согласия, порядок представления налоговым органом сведений, составляющих налоговую тайну, иному лицу в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение пунктом - Федеральный закон от 01.05.2022 № 120-ФЗ)\n\nДоступ к сведениям, составляющим налоговую тайну, имеют должностные лица, определяемые соответственно федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, федеральным органом исполнительной власти, уполномоченным в области внутренних дел, федеральным государственным органом, осуществляющим полномочия в сфере уголовного судопроизводства, федеральным органом исполнительной власти, уполномоченным в области таможенного дела. (В редакции федеральных законов от 29.06.2004 № 58-ФЗ; от 26.06.2008 № 103-ФЗ; от 28.12.2010 № 404-ФЗ)\n\nержащих составляющие налоговую тайну сведения, либо разглашение таких сведений влечет ответственность, предусмотренную федеральными законами.\n\nДоступ к сведениям, составляющим налоговую тайну, в государственных органах, органах местного самоуправления или организациях, в которые такие сведения поступили в соответствии с законодательством Российской Федерации о противодействии коррупции, имеют должностные лица, определяемые руководителями этих государственных органов, органов местного самоуправления или организаций.\n\n(Дополнение пунктом - Федеральный закон от 21.11.2011 № 329-ФЗ) (В редакции Федерального закона от 03.12.2012 № 231-ФЗ)\n\nДоступ к указанным в настоящем пункте сведениям, составляющим налоговую тайну, в государственных органах, в которые такие сведения поступили в соответствии с нормативными правовыми актами Президента Российской Федерации, Правительства Российской Федерации, имеют должностные лица, определяемые руководителями этих государственных органов.\n\n(Дополнение пунктом - Федеральный закон от 28.06.2013 № 134-ФЗ)\n\n1) такие сведения признаются налоговой тайной без исключений, установленных подпунктами 1 - 3 и 5 - 8 пункта 1 настоящей статьи;\n\n2) разглашение таких сведений и утрата представленных специальных деклараций и (или) прилагаемых к ним документов и (или) сведений являются основанием для привлечения к уголовной ответственности за незаконное разглашение сведений, составляющих налоговую тайну, в соответствии с Уголовным кодексом Российской Федерации;\n\n3) должностное лицо налогового органа, которому такие сведения стали известны, не может быть привлечено к ответственности за отказ от дачи показаний по обстоятельствам, которые стали ему известны из сведений, указанных в абзаце первом настоящего пункта;\n\n4) такие сведения могут быть истребованы у налогового органа только по запросу самого декларанта, признаваемого таковым в соответствии с указанным в абзаце первом настоящего пункта Федеральным законом;\n\n5) в случае необходимости подтверждения факта представления в налоговый орган специальной декларации и документов и (или) сведений, прилагаемых к декларации, и достоверности содержащихся в них сведений должностное лицо органа государственной власти или банка, которому в качестве основания для предоставления гарантий, предусмотренных указанным в абзаце первом настоящего пункта Федеральным законом, была представлена копия специальной декларации с отметкой налогового органа о ее принятии, вправе направить ее в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, для сверки с оригиналом специальной декларации, находящейся на централизованном хранении. Федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в пятидневный срок после получения такой копии специальной декларации направляет ответное уведомление о том, соответствует либо не соответствует полученная копия специальной декларации оригиналу.\n\n(Дополнение пунктом - Федеральный закон от 08.06.2015 № 150-ФЗ)\n\nДоступ к указанным в настоящем пункте сведениям, составляющим налоговую тайну, в финансовых органах субъектов Российской Федерации имеют должностные лица, определяемые руководителями этих финансовых органов.\n\n(Дополнение пунктом - Федеральный закон от 03.08.2018 № 302-ФЗ)\n\nДоступ к указанным в настоящем пункте сведениям, составляющим налоговую тайну, в органах субъектов Российской Федерации, уполномоченных в сфере социальной защиты населения, в Фонде пенсионного и социального страхования Российской Федерации имеют должностные лица, определяемые руководителями указанных органов и фонда соответственно. (В редакции  Федерального закона от 14.07.2022 № 239-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 26.03.2020 № 68-ФЗ) (В редакции Федерального закона от 01.05.2022 № 120-ФЗ)\n\n11. Положения настоящей статьи в части запрета на разглашение сведений, составляющих налоговую тайну, требований к специальному режиму хранения указанных сведений и доступа к ним, ответственности за утрату документов, содержащих указанные сведения, или за разглашение указанных сведений распространяются на сведения о налогоплательщиках, плательщиках страховых взносов, поступившие от налоговых органов в федеральные органы государственной власти, органы государственной власти субъектов Российской Федерации, органы местного самоуправления для осуществления оценки налоговых расходов в соответствии со статьей 1743 Бюджетного кодекса Российской Федерации.\n\nДоступ к указанным в настоящем пункте сведениям, составляющим налоговую тайну, поступившим от налоговых органов в федеральные органы государственной власти, органы государственной власти субъектов Российской Федерации, органы местного самоуправления, имеют должностные лица, определяемые руководителями этих органов.\n\n(Дополнение пунктом - Федеральный закон от 23.11.2020 № 374-ФЗ)\n\nоб использовании (о неиспользовании) налогоплательщиком - физическим лицом права на получение налогового вычета, предусмотренного подпунктом 2 пункта 1 статьи 2191 настоящего Кодекса, в течение срока действия договора на ведение индивидуального инвестиционного счета и иных договоров, прекращенных с переводом активов на этот индивидуальный инвестиционный счет в порядке, предусмотренном пунктом 91 статьи 2261 настоящего Кодекса;\n\nо наличии (об отсутствии) у налогоплательщика в течение срока действия договора на ведение индивидуального инвестиционного счета других договоров на ведение индивидуального инвестиционного счета, за исключением случаев прекращения договора с переводом всех активов, учитываемых на индивидуальном инвестиционном счете, на другой индивидуальный инвестиционный счет, открытый тому же физическому лицу.\n\nДоступ к указанным в настоящем пункте сведениям, составляющим налоговую тайну, у налоговых агентов имеют работники, определяемые руководителями (заместителями руководителей) таких организаций.\n\n(Дополнение пунктом - Федеральный закон от 20.04.2021 № 100-ФЗ)\n\n13. Положения настоящей статьи в части запрета на разглашение сведений, составляющих налоговую тайну, требований к специальному режиму хранения указанных сведений и доступа к ним, ответственности за утрату документов, содержащих указанные сведения, или за разглашение указанных сведений распространяются на сведения о снятии с учета в налоговых органах физических лиц в связи со смертью, поступившие от налоговых органов в банки в целях, установленных Федеральным законом \"О банках и банковской деятельности\".\n\nДоступ к указанным в настоящем пункте сведениям, составляющим налоговую тайну, в банках имеют должностные лица, определяемые руководителями таких банков.\n\n(Дополнение пунктом - Федеральный закон от 19.12.2022 № 552-ФЗ)\n\n14. Положения настоящей статьи в части запрета на разглашение сведений, составляющих налоговую тайну, требований к специальному режиму хранения указанных сведений и доступа к ним, ответственности за утрату документов, содержащих указанные сведения, за разглашение указанных сведений распространяются на сведения, указанные в абзаце шестом подпункта 2 и абзаце пятом подпункта 4 пункта 1 статьи 213, абзаце восьмом пункта 2 статьи 2131 настоящего Кодекса, поступившие от налогового органа страховым организациям и негосударственным пенсионным фондам в рамках обмена информацией в соответствии с правилами обмена информацией о подтверждении неполучения налогоплательщиком социального налогового вычета либо подтверждении факта получения налогоплательщиком суммы предоставленного социального налогового вычета, предусмотренного подпунктом 4 пункта 1 статьи 219 настоящего Кодекса.\n\nДоступ к указанным в настоящем пункте сведениям, составляющим налоговую тайну, в страховых организациях и негосударственных пенсионных фондах имеют работники, определяемые руководителями (заместителями руководителей) таких страховых организаций и негосударственных пенсионных фондов.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n15. Положения настоящей статьи в части запрета на разглашение сведений, составляющих налоговую тайну, требований к специальному режиму хранения указанных сведений и доступа к ним, ответственности за утрату документов, содержащих указанные сведения, или за разглашение указанных сведений распространяются на сведения, составляющие налоговую тайну, передаваемые налоговыми органами в соответствии с Федеральным законом от 12 декабря 2023 года № 565-ФЗ \"О занятости населения в Российской Федерации\" в межведомственные комиссии субъектов Российской Федерации по противодействию нелегальной занятости, федеральный орган исполнительной власти, осуществляющий функции по федеральному государственному контролю (надзору) в сфере труда, занятости, альтернативной гражданской службы, его территориальные органы.\n\nДоступ к предусмотренным настоящим пунктом сведениям, составляющим налоговую тайну, в указанных комиссиях и органах имеют должностные лица, определяемые руководителями указанных комиссий и органов соответственно.\n\n(Дополнение пунктом - Федеральный закон от 30.09.2024 № 335-ФЗ)","article_title":"Статья 102. Налоговая тайна","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1ff67677a8187330a305e0efa1788dfc436a9650ed67848c59760509de4ed230"},{"code_id":"NK_RF","article_number":"103.1","version_date":"2000-07-31","article_text":"(Дополнение статьей - Федеральный закон от 04.11.2005 № 137-ФЗ) (Утратила силу - Федеральный закон от 27.07.2006 № 137-ФЗ)","article_title":"Статья 103.1. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3f74ad90aaaec781813e1a001803c07c5531d9525d6f363baa8c564e1bc4e4a7"},{"code_id":"NK_RF","article_number":"104","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 29.11.2010 № 324-ФЗ)\n\nДо обращения в суд налоговый орган обязан предложить лицу, привлекаемому к ответственности за совершение налогового правонарушения, добровольно уплатить соответствующую сумму налоговой санкции. (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 27.07.2006 № 137-ФЗ)\n\nВ случае, если лицо, привлекаемое к ответственности за совершение налогового правонарушения, отказалось добровольно уплатить сумму налоговой санкции, налоговый орган обращается в суд с заявлением о взыскании с данного лица налоговой санкции, установленной настоящим Кодексом, за совершение данного налогового правонарушения.  (В редакции  федеральных законов от 09.07.1999 № 154-ФЗ, от 27.07.2006 № 137-ФЗ, от 29.11.2010 № 324-ФЗ, от 14.07.2022 № 263-ФЗ)\n\nК заявлению прилагаются решение налогового органа и другие материалы дела, полученные в процессе налоговой проверки. (В редакции Федерального закона от 29.11.2010 № 324-ФЗ)","article_title":"Статья 104. Заявление о взыскании налоговой санкции","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"27943e861dd594af193d93f47228f9d3540e170813d9773273dfece0fe50ff2e"},{"code_id":"NK_RF","article_number":"105","version_date":"2000-07-31","article_text":"Исполнение вступивших в законную силу решений судов о взыскании налоговых санкций с организаций, которым открыты лицевые счета, производится в порядке, установленном бюджетным законодательством Российской Федерации. (Дополнение абзацем - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\nЗАВИСИМЫМИ ЛИЦАМИ. СОГЛАШЕНИЕ О ЦЕНООБРАЗОВАНИИ. ДОКУМЕНТАЦИЯ ПО МЕЖДУНАРОДНЫМ ГРУППАМ КОМПАНИЙ\n\n(Наименование в редакции Федерального закона от 27.11.2017 № 340-ФЗ)\n\n(Дополнение разделом - Федеральный закон от 18.07.2011 № 227-ФЗ)","article_title":"Статья 105. Рассмотрение дел и исполнение решений о взыскании налоговых санкций","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6711137332c18611b1ee0a1cfbfd0a47a76f44ecc44b4f97795a5ca4cd99ef24"},{"code_id":"NK_RF","article_number":"105.1","version_date":"2000-07-31","article_text":"1. Если особенности отношений между лицами могут оказывать влияние на условия и (или) результаты сделок, совершаемых этими лицами, и (или) экономические результаты деятельности этих лиц или деятельности представляемых ими лиц, указанные в настоящем пункте лица признаются взаимозависимыми для целей налогообложения (далее - взаимозависимые лица).\n\nДля признания взаимной зависимости лиц учитывается влияние, которое может оказываться в силу участия одного лица в капитале других лиц, в соответствии с заключенным между ними соглашением либо при наличии иной возможности одного лица определять решения, принимаемые другими лицами. При этом такое влияние учитывается независимо от того, может ли оно оказываться одним лицом непосредственно и самостоятельно или совместно с его взаимозависимыми лицами, признаваемыми таковыми в соответствии с настоящей статьей.\n\n2. С учетом пункта 1 настоящей статьи в целях настоящего Кодекса взаимозависимыми лицами признаются:\n\n1) организации в случае, если одна организация прямо и (или) косвенно участвует в другой организации и доля такого участия составляет более 25 процентов;\n\n2) физическое лицо и организация в случае, если такое физическое лицо прямо и (или) косвенно участвует в такой организации и доля такого участия составляет более 25 процентов;\n\n3) организации в случае, если одно и то же лицо прямо и (или) косвенно участвует в этих организациях и доля такого участия в каждой организации составляет более 25 процентов;\n\n4) организация и лицо (в том числе физическое лицо совместно с его взаимозависимыми лицами, указанными в подпункте 11 настоящего пункта), имеющее полномочия по назначению (избранию) единоличного исполнительного органа этой организации или по назначению (избранию) не менее 50 процентов состава коллегиального исполнительного органа или совета директоров (наблюдательного совета) этой организации;\n\n5) организации, единоличные исполнительные органы которых либо не менее 50 процентов состава коллегиального исполнительного органа или совета директоров (наблюдательного совета) которых назначены или избраны по решению одного и того же лица (физического лица совместно с его взаимозависимыми лицами, указанными в подпункте 11 настоящего пункта);\n\n6) организации, в которых более 50 процентов состава коллегиального исполнительного органа или совета директоров (наблюдательного совета) составляют одни и те же физические лица совместно с взаимозависимыми лицами, указанными в подпункте 11 настоящего пункта;\n\n7) организация и лицо, осуществляющее полномочия ее единоличного исполнительного органа;\n\n8) организации, в которых полномочия единоличного исполнительного органа осуществляет одно и то же лицо;\n\n9) организации и (или) физические лица в случае, если доля прямого участия каждого предыдущего лица в каждой последующей организации составляет более 50 процентов;\n\n10) физические лица в случае, если одно физическое лицо подчиняется другому физическому лицу по должностному положению;\n\n11) физическое лицо, его супруг (супруга), родители (в том числе усыновители), дети (в том числе усыновленные), полнородные и неполнородные братья и сестры, опекун (попечитель) и подопечный;\n\n12) организации в случае, если физическое лицо, имеющее в одной из таких организаций долю прямого и (или) косвенного участия более 25 процентов и (или) полномочия по назначению (избранию) единоличного исполнительного органа организации или по назначению (избранию) не менее 50 процентов состава коллегиального исполнительного органа или совета директоров (наблюдательного совета) организации, и физическое лицо, имеющее в другой из таких организаций указанную долю участия и (или) указанные полномочия, признаются взаимозависимыми лицами в соответствии с подпунктом 11 настоящего пункта. В целях настоящего подпункта наличие полномочий по назначению (избранию) единоличного исполнительного органа организации или по назначению (избранию) не менее 50 процентов состава коллегиального исполнительного органа или совета директоров (наблюдательного совета) организации определяется для физического лица совместно с его взаимозависимыми лицами, указанными в подпункте 11 настоящего пункта; (Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n13) лицо и организация, которые в соответствии со статьей 2513 настоящего Кодекса признаются в целях настоящего Кодекса соответственно контролирующим лицом и контролируемой иностранной компанией; (Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n14) организации, которые в соответствии со статьей 2513 настоящего Кодекса признаются в целях настоящего Кодекса контролируемыми иностранными компаниями и контролирующим лицом которых является одно и то же лицо. (Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\nУказанные в настоящем пункте организации могут быть признаны взаимозависимыми по иным основаниям, предусмотренным настоящей статьей.","article_title":"Статья 105.1. Взаимозависимые лица","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"74c663d5209f0de091ab0959f9f9f1c83ace922d1c0876d4bba1a55e26056964"},{"code_id":"NK_RF","article_number":"105.10","version_date":"2000-07-31","article_text":"1. Метод цены последующей реализации является методом определения соответствия цены в анализируемой сделке рыночной цене на основании сопоставления валовой рентабельности, полученной лицом, совершившим анализируемую сделку, при последующей реализации (перепродаже) им товара, приобретенного им в этой анализируемой сделке (группе однородных сделок), с рыночным интервалом валовой рентабельности, определенным в порядке, предусмотренном статьей 1058 настоящего Кодекса.\n\n2. Использование метода цены последующей реализации является приоритетным по сравнению с другими методами для определения соответствия рыночным ценам цен, по которым товар приобретается в рамках анализируемой сделки и перепродается без переработки в рамках сделки, сторонами которой являются лица, не признаваемые взаимозависимыми. Указанный метод используется в случае, если лицо, осуществляющее перепродажу, не владеет объектами нематериальных активов, оказывающими существенное влияние на уровень его валовой рентабельности. Метод цены последующей реализации может быть использован также в случаях, когда при перепродаже товара осуществляются следующие операции:\n\n1) подготовка товара к перепродаже и транспортировке (деление товаров на партии, формирование отправок, сортировка, переупаковка);\n\n2) смешивание товаров, если характеристики конечной продукции (полуфабрикатов) существенно не отличаются от характеристик смешиваемых товаров.\n\n3. В случае, если последующая реализация товара в сделках, совершенных в сопоставимых коммерческих и (или) финансовых условиях между лицом, осуществляющим перепродажу, и лицами (лицом), не являющимися (не являющимся) его взаимозависимыми лицами, осуществляется по разным ценам, при определении интервала рентабельности в качестве цены последующей реализации товара используется средневзвешенная цена этого товара по всем таким сделкам.\n\n4. В случае, если валовая рентабельность лица, осуществляющего перепродажу, находится в пределах интервала рентабельности, определенного в порядке, предусмотренном статьей 1058 настоящего Кодекса, для целей налогообложения признается, что цена, по которой товар приобретен в контролируемой сделке, соответствует рыночной цене.\n\n5. В случае, если валовая рентабельность лица, осуществляющего перепродажу, меньше минимального значения интервала рентабельности, определенного в порядке, предусмотренном статьей 1058 настоящего Кодекса, или превышает максимальное значение интервала рентабельности, определенного в порядке, предусмотренном статьей 1058 настоящего Кодекса, для целей налогообложения принимается цена, примененная в контролируемой сделке, определяемая исходя из фактической цены последующей реа\n\nлизации товара и валовой рентабельности, которая соответствует медианному значению интервала рентабельности. (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)","article_title":"Статья 105.10. Метод цены последующей реализации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"09f85b4ac687c194f68711fda545d2147c678c6ccba44bc082cc1d65e3321bc1"},{"code_id":"NK_RF","article_number":"105.11","version_date":"2000-07-31","article_text":"1. Затратный метод является методом определения соответствия цены в анализируемой сделке рыночной цене на основании сопоставления валовой рентабельности затрат лица, являющегося стороной анализируемой сделки (группы анализируемых однородных сделок), с рыночным интервалом валовой рентабельности затрат в сопоставимых сделках, определенным в порядке, предусмотренном статьей 1058 настоящего Кодекса.\n\n2. Затратный метод может применяться, в частности, в следующих случаях:\n\n1) при выполнении работ (оказании услуг) лицами, являющимися взаимозависимыми с продавцом (за исключением случаев, когда при выполнении работ (оказании услуг) используются нематериальные активы, оказывающие существенное влияние на уровень рентабельности затрат продавца);\n\n2) при оказании услуг по управлению денежными средствами, включая осуществление торговых операций на рынке ценных бумаг и (или) валютном рынке;\n\n3) при оказании услуг по исполнению функций единоличного исполнительного органа организации;\n\n4) при продаже сырья или полуфабрикатов лицам, являющимся взаимозависимыми с продавцом;\n\n5) при реализации товаров (работ, услуг) по долгосрочным договорам между взаимозависимыми лицами.\n\n3. В случае, если валовая рентабельность затрат продавца, являющегося стороной анализируемой сделки, по указанной сделке находится в пределах интервала рентабельности, определенного в порядке, предусмотренном статьей 1058 настоящего Кодекса, для целей налогообложения признается, что цена, примененная в анализируемой сделке, соответствует рыночным ценам.","article_title":"Статья 105.11. Затратный метод","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"23978a0ccc268b8f8a01536f1e5599db070dde77aac7b0796a86998a992a4e3a"},{"code_id":"NK_RF","article_number":"105.12","version_date":"2000-07-31","article_text":"1. Метод сопоставимой рентабельности заключается в сопоставлении операционной рентабельности, сложившейся у лица, являющегося стороной анализируемой сделки, с рыночным интервалом операционной рентабельности в сопоставимых сделках, определенным в порядке, предусмотренном статьей 1058 настоящего Кодекса.\n\n2. Метод сопоставимой рентабельности может использоваться, в частности, в случае отсутствия или недостаточности информации, на основании которой можно обоснованно сделать вывод о наличии необходимой степени сопоставимости коммерческих и (или) финансовых условий сопоставляемых сделок и использовать методы, указанные в подпунктах 2 и 3 пункта 1 статьи 1057 настоящего Кодекса.\n\n3. Для целей настоящей статьи могут использоваться следующие показатели операционной рентабельности, определяемые в соответствии с пунктом 1 статьи 1058 настоящего Кодекса:\n\n1) рентабельность продаж;\n\n2) рентабельность затрат;\n\n3) рентабельность коммерческих и управленческих расходов;\n\n4) рентабельность активов;\n\n5) иной показатель рентабельности, отражающий взаимосвязь между осуществляемыми функциями, используемыми активами и принимаемыми экономическими (коммерческими) рисками и уровнем вознаграждения.\n\n4. При выборе конкретного показателя рентабельности учитываются вид деятельности, осуществляемый лицом, являющимся стороной анализируемой сделки, осуществляемые им функции, используемые активы и принимаемые экономические (коммерческие) риски, полнота, достоверность и сопоставимость данных, используемых для расчета соответствующей рентабельности, а также экономическая обоснованность такого показателя.\n\n5. Для целей применения настоящей статьи показатели рентабельности используются с учетом следующих особенностей:\n\n1) рентабельность продаж используется при последующей перепродаже товаров, приобретенных у лиц, являющихся взаимозависимыми с лицом, осуществляющим перепродажу, лицам, которые не являются взаимозависимыми с ним, а также при последующей перепродаже товаров, приобретенных у лиц, не являющихся взаимозависимыми с лицом, осуществляющим перепродажу, лицам, которые являются взаимозависимыми с ним;\n\n2) валовая рентабельность коммерческих и управленческих расходов используется в случаях, указанных в подпункте 1 настоящего пункта, если лицо, осуществляющее перепродажу, несет незначительные экономические (коммерческие) риски при приобретении и последующей перепродаже товаров в непродолжительный период и при этом существует прямая взаимосвязь между величиной валовой прибыли от продаж лица, осуществляющего перепродажу, и величиной осуществленных им коммерческих и управленческих расходов;\n\n3) рентабельность затрат используется при выполнении работ, оказании услуг, а также при производстве товаров;\n\n4) рентабельность активов используется при производстве товаров (в частности, если анализируемые сделки совершаются лицами, которые осуществляют капиталоемкую деятельность).\n\n6. При использовании метода сопоставимой рентабельности с рыночным интервалом рентабельности сопоставляется рентабельность той стороны анализируемой сделки, которая отвечает следующим требованиям:\n\n1) сторона анализируемой сделки осуществляет функции, вклад которых в полученную прибыль по сделкам, последовательно совершенным с одним и тем же товаром, меньше, чем вклад другой стороны анализируемой сделки;\n\n2) сторона анализируемой сделки принимает меньшие экономические (коммерческие) риски, чем другая сторона анализируемой сделки;\n\n3) сторона анализируемой сделки не владеет объектами нематериальных активов, оказывающими существенное влияние на уровень рентабельности.\n\n7. В случае, если сторона анализируемой сделки не отвечает требованиям, предусмотренным подпунктами 1 - 3 пункта 6 настоящей статьи, для сопоставления с рыночным интервалом рентабельности выбирается та сторона анализируемой сделки, которая в наибольшей степени отвечает указанным требованиям.\n\n8. В случае, если рентабельность по контролируемой сделке находится в пределах интервала рентабельности, определенного в порядке, предусмотренном статьей 1058 настоящего Кодекса, для целей налогообложения признается, что цена, примененная в этой сделке, соответствует рыночным ценам.\n\n9. В случае, если рентабельность по контролируемой сделке меньше минимального значения интервала рентабельности, определенного в порядке, предусмотренном статьей 1058 настоящего Кодекса, или превышает максимальное значение интервала рентабельности, определенного в порядке, предусмотренном статьей 1058 настоящего Кодекса, для целей налогообложения учитывается медианное значение интервала рентабельности.\n\nНа основании учитываемого в соответствии с настоящим пунктом медианного значения интервала рентабельности осуществляется корректировка прибыли (дохода, выручки) по контролируемой сделке в целях налогообложения.\n\n(Пункт в редакции  Федерального закона от 27.11.2023 № 539-ФЗ)","article_title":"Статья 105.12. Метод сопоставимой рентабельности","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bc8e9a92607fa7a104dcaac277f967c8e56157de7c0473e22495b608231b9ee5"}]$law7d0048$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
